 qa=[dict(t='q', q='阅读提后3:16、17。这段经文如何同时强调圣经的权威与默示？', a=[('table',['','经文','意义'],[['默示','“圣经都是上帝所默示的”','来源是上帝，而且是“都”，不是部分'],['权威①','“于教训”','告诉我们什么是对的'],['权威②','“督责”','指出我们哪里错了'],['权威③','“使人归正”','告诉我们如何改正'],['权威④','“教导人学义”','教导我们如何持守正路'],['目的','“叫属上帝的人得以完全，预备行各样的善事”','装备人去生活和服事']]), '因为圣经出于上帝（默示），所以它有资格教训、督责和纠正我们（权威）。**默示是权威的根源，权威是默示的结果。**']),
     dict(t='q', q='阅读路24:27。耶稣复活之后，祂用什么来帮助两位灰心的门徒明白祂独特的使命？', a=['祂用的是**圣经**：“从摩西和众先知起，凡经上所指着自己的话，都给他们讲解明白了。”祂可能讲到：', ('ul',['创3:15 女人的后裔要伤蛇的头','出12章 逾越节的羔羊','民21:8、9 挂在杆子上的铜蛇（参约3:14）','诗22篇 “我的上帝，我的上帝，为什么离弃我？”','赛53章 “他为我们的过犯受害”','但9:26 “受膏者必被剪除”']), '结果：他们的心“火热”（24:32），并且“立时起身，回耶路撒冷去”（24:33）。灰心变成了使命。']),
     dict(t='q', q='为什么耶稣在向往以马忤斯去的那两位门徒表明身份之前，要先把他们引到圣经面前？这件事告诉我们，上帝的话语对我们而言，为什么必须是信仰根本的基础？', a=[('ul',['**经验会消失，圣经会留下**：耶稣一被认出，就“不见了”（24:31），但他们手中的圣经仍在。','**他们需要明白十字架是计划，而不是失败**：“基督这样受害，又进入他的荣耀，岂不是应当的吗？”（24:26）只有圣经能解释十字架。','**我们今天也看不见耶稣**：我们和那两位门徒不同，我们没有机会看见祂擘饼；但我们拥有同样的圣经。“那没有看见就信的有福了。”（约20:29）']), '建立在经验上的信心，会随着情绪起伏；建立在圣经上的信心，才能在“看不见”的日子站立得住。'], my=True)],
